    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx, int(m.group(2))

def parse_shared_strings(z):
    if 'xl/sharedStrings.xml' not in z.namelist():
        return []
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    out = []
    for si in root.findall('m:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{%s}t' % NS['m']))
        out.append(text)
    return out

def parse_sheet(z, sheet_path):
    root = ET.fromstring(z.read(sheet_path))
    rows = {}
    for c in root.iter('{%s}c' % NS['m']):
        ref = c.get('r')
        if not ref:
            continue
        ci, ri = col_to_idx(ref)
        t = c.get('t')
        v = c.find('m:v', NS)
        isel = c.find('m:is', NS)
        value = None
        if t == 's' and v is not None:
            value = shared[v.text if False else int(v.text)]
        elif t == 'inlineStr' and isel is not None:
            value = ''.join(x.text or '' for x in isel.iter('{%s}t' % NS['m']))
        elif v is not None:
            value = v.text
        rows.setdefault(ri, {})[ci] = (t, value)
    return rows

