for name, path in sheets:
    if not path.startswith('xl/'):
        path = 'xl/' + path
    print(f"=== Sheet: {name} ===")
    rows = parse_sheet(z, path)
    for ri in sorted(rows):
        cells = rows[ri]
        for ci in sorted(cells):
            t, val = cells[ci]
            print(f"  R{ri}C{ci} (t={t}): {val!r}")

