import zipfile
import xml.etree.ElementTree as ET
import re

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    return sum((ord(c) - 64) * 26 ** (len(m.group(1)) - 1 - i) for i, c in enumerate(m.group(1))), int(m.group(2))

z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

rows = {}
for c in root.iter('{%s}c' % NS['m']):
    ref = c.get('r')
    ci, ri = col_to_idx(ref)
    t = c.get('t')
    v = c.find('m:v', NS)
    isel = c.find('m:is', NS)
    val = None
    if t == 'inlineStr' and isel is not None:
        val = ''.join(x.text or '' for x in isel.iter('{%s}t' % NS['m']))
    elif v is not None:
        val = v.text
    rows.setdefault(ri, {})[ci] = (t, val)

expenses = []
for ri in range(11, 23):
    t, val = rows.get(ri, {}).get(3, (None, None))
    category = rows.get(ri, {}).get(1, (None, None))[1]
    item = rows.get(ri, {}).get(2, (None, None))[1]
    amount = float(val) if val is not None else 0.0
    expenses.append((category, item, amount))

by_cat = {}
for cat, item, amt in expenses:
    by_cat.setdefault(cat, 0.0)
    by_cat[cat] += amt

for cat, item, amt in expenses:
    print(f"{cat:<16} {item:<20} {amt:>10.2f}")
print("-" * 50)
for cat, total in by_cat.items():
    print(f"{cat:<16} subtotal {total:>10.2f}")
print("-" * 50)
print(f"{'TOTAL EXPENSES':<16} {'':<20} {sum(a for _, _, a in expenses):>10.2f}")

